【t2 最小 PoC 交付（anchor-engineer）——可转交用户粘贴测试】

脚本（全文，另存 ~/tmp-anchor/poc-art-entry.js，可直接粘贴 LSPFRIFA 详情页）：
```
/*
 * LSPFRIFA 最小 PoC —— ArtMethod 入口地址 + Interceptor.attach（单次运行两步验证）
 * runtime: frida-gumjs devkit 17.9.3 (GumJS/QuickJS), Android 15 / ART 35
 * 只改下面 4 个常量(默认 MODE A)：
 */
var TARGET_CLASS     = "android.app.Instrumentation";   // MODE A: boot 类,必为 AOT 编译代码
var TARGET_METHOD    = "callApplicationOnCreate";       // (android.app.Application) 每次启动必经
var TARGET_SIGNATURE = null;                            // 多 overload 时填 'android.content.Context' 等
/*
 * MODE B(目标应用方法,把上面换成):
 *   TARGET_CLASS     = "com.example.application.GlobalApplication";
 *   TARGET_METHOD    = "onCreate";
 * 注意: 应用 dex 方法首次调用前可能未编译 -> 脚本会打 WARN 并跳过 attach(见判定表)。
 */

function log (msg) {
  try { console.log("[poc] " + msg); } catch (e) {}
  try { send("[poc] " + msg); } catch (e) {}
}

Java.perform(function () {
  var pointerSize = Process.pointerSize;

  function resolveClass (className) {
    try { return Java.use(className); } catch (e) { /* fallthrough */ }
    var saved = Java.classFactory.loader, found = null;
    try {
      var loaders = Java.enumerateClassLoadersSync();
      for (var i = 0; i !== loaders.length && found === null; i++) {
        Java.classFactory.loader = loaders[i];
        try { found = Java.use(className); } catch (e2) {}
      }
    } finally { try { Java.classFactory.loader = saved; } catch (e3) {} }
    if (found === null) throw new Error("Class not found: " + className);
    return found;
  }

  /* jmethodID -> ArtMethod*: ART35 (AOSP jni_id_manager.cc): (id%2)==0 => 直接就是 ArtMethod* */
  var W = resolveClass(TARGET_CLASS);
  var m = W[TARGET_METHOD];
  if (TARGET_SIGNATURE !== null) m = m.overload(TARGET_SIGNATURE);
  var jmethodId = m.handle;                     // == jmethodID (opaque)
  var artMethod = (jmethodId.and(1).toInt32() === 1)
    ? (function () {                            // opaque 兜底: libart 导出 DecodeMethodId
        var sym = null;
        try { sym = Module.getGlobalExportByName('_ZN3art3jni12JniIdManager14DecodeMethodIdEP10_jmethodID'); } catch (e) {}
        if (sym === null) { try { sym = Module.findExportByName('libart.so', '_ZN3art3jni12JniIdManager14DecodeMethodIdEP10_jmethodID'); } catch (e2) {} }
        if (sym === null) throw new Error('DecodeMethodId symbol not found');
        var vm = Java.vm.handle, rt = vm.add(pointerSize).readPointer(), mgr = null;
        for (var off = 0; off !== 120 * pointerSize; off += pointerSize) {
          if (rt.add(off).readPointer().equals(vm)) { mgr = rt.add(off - pointerSize).readPointer(); break; }
        }
        if (mgr === null) throw new Error('cannot locate jni_id_manager_');
        return new NativeFunction(sym, 'pointer', ['pointer', 'pointer'])(mgr, jmethodId);
      })()
    : jmethodId;

  /* ArtMethod 偏移(64位 ART35 推断值, 来源=AOSP runtime/art_method.h 布局推算):
   *   0x00 declaring_class_ | 0x04 access_flags_ | 0x08 dex_method_index_ | 0x0C method_index_
   *   0x0E hotness_count_ | 0x10 data_ | 0x18 entry_point_from_quick_compiled_code_
   *   [需真机验证: flags 自检不过即视为偏移不符,拒绝往下走] */
  var OFF_FLAGS = 0x04, OFF_DATA = 0x10, OFF_ENTRY = 0x18;
  var flags = artMethod.add(OFF_FLAGS).readU32();
  var data  = artMethod.add(OFF_DATA).readPointer();
  var entry = artMethod.add(OFF_ENTRY).readPointer();
  log("STEP1+ jmethodID=" + jmethodId + " ArtMethod=" + artMethod
    + " flags=0x" + flags.toString(16) + " data_=" + data + " entry(quickCode)=" + entry);

  var low16 = flags & 0xFFFF;
  if (low16 === 0 || low16 === 0xFFFF || entry.isNull()) {
    log("FAIL: flags/entry 自检不符(偏移可能已变,或 id 解码失败) —— 停在这,别 attach");
    return;
  }

  /* 共享 thunk 检测: entry 落在 libart.so 内 => 解释器/解析桥(方法未编译),x0=ArtMethod* 非 this */
  var libart = null;
  try { libart = Process.getModuleByName('libart.so'); } catch (e) {}
  if (libart !== null &&
      entry.compare(libart.base) >= 0 && entry.compare(libart.base.add(libart.size)) < 0) {
    log("WARN: entry 在 libart.so 内(共享入口/方法未编译): " + entry
      + " —— 不能 attach(会拦到所有走该入口的调用且 x0 是 ArtMethod* 非 this)。"
      + " 请换 MODE A(boot 类必编译) 或换成会被重复调用的方法(如 Activity.onResume)");
    return;
  }

  try {
    Interceptor.attach(entry, {
      onEnter: function (args) {
        log("STEP2+ HIT " + TARGET_CLASS + "." + TARGET_METHOD + " @ " + entry
          + " | x0(this/首参)=" + this.context.x0 + " x1=" + this.context.x1
          + " x2=" + this.context.x2 + " tid=" + this.threadId);
      },
      onLeave: function (retval) {
        log("STEP2- LEAVE " + TARGET_CLASS + "." + TARGET_METHOD + " retval(x0)=" + retval);
      }
    });
    log("STEP2+ ATTACHED OK: " + TARGET_CLASS + "." + TARGET_METHOD + " entry=" + entry + " (等待触发...)");
  } catch (e) {
    log("FAIL: Interceptor.attach 失败: " + e
      + " (常见: 代码页不可写/mprotect 被拒、入口 prologue 无法重定位(PAC 等) —— 换方法再试)");
  }
});
```

【结果判定表】
| 现象 | 判定 |
|---|---|
| 看到 `STEP1+ jmethodID=... ArtMethod=... flags=0x... entry=0x...` 且 entry 非 0、flags 低16位非 0x0/0xffff | ①地址可获取【通过】（0x18 偏移与 AOSP 期望一致=探测正常） |
| 随后 `STEP2+ ATTACHED OK` + 触发后 `STEP2+ HIT` + `STEP2- LEAVE` 各一行 | ②attach 生效【通过】＝ART35 锚点链路整体可用 |
| `Class not found: ...` | 类名错/在别的 classloader→脚本已自动枚举兜底；还不行告诉 captain 目标 app 真实类名 |
| `has more than one overload`（handle 抛歧义） | 填 TARGET_SIGNATURE（如 'android.content.Context'） |
| `FAIL: flags/entry 自检不符` | ArtMethod 布局与预期不符或 id 解码失败→把 STEP1 行回传，我换探测版 |
| `WARN: entry 在 libart.so 内` | 方法未编译→换 MODE A 或换成重复调用方法；这是「GlobalApplication.onCreate 首次调用前可能未编译」的正常表现 |
| `FAIL: Interceptor.attach 失败` | 代码页不可写(mprotect/SELinux)或 prologue 无法重定位(PAC)→换更普通的方法再测；把错误全文回传 |
| 无任何 [poc] 日志 | 脚本没执行→查 LSPFRIFA 端脚本加载/浏览器日志 |

【偏移来源与风险】0x04/0x10/0x18 = AOSP android15-release runtime/art_method.h 成员顺序推算（【已确认·AOSP】【需真机验证】，脚本内置 flags/entry 自检，不符即停不误伤）。

【升级 17.17.0 可选顺手项（不用现在做）】未来若升 devkit：收益=新 gum interceptor 修复+新版 java bridge（Java API 稍有变化），本 PoC 已按 17 API 写（Module.getGlobalExportByName 等+兼容 try），升完可直接跑；但 t1 已确认无 A15 修复的前提下，升级非必要，先 PoC、后升级。

【t2 状态说明】t2 此前已置 completed（终端态不可再 update），本产出以本消息提交，若 captain 需要我以新任务对象补正式输出请创建任务给我。

【t3 完成（anchor-engineer）——算法助手 Java bridge 补丁提取+移植评估】完整分析见 ~/tmp-anchor/bootstrap-patch-analysis.md，要点：

【提取（逐字，.so rodata 0xb52xx，附原文文件）】
```js
function patchJavaBridge(source) {
    const jvmtiProbe = 'null===f&&(f=[De(p,this.artRuntime)]),f[0]';
    if (!source.includes(jvmtiProbe)) {
      console.error('Unable to disable the embedded Java bridge JVMTI probe');
      return source;
    }
    return source.replace(jvmtiProbe, 'null===f&&(f=[null]),f[0]');
}
```
语义：把 bridge（minified bundle）里「尝试获取 JVMTI env 并缓存」的一行替换为「缓存恒 [null]」——【禁用内嵌 Java bridge 的 JVMTI 探测】。installFrida17Compatibility=纯 frida17 API 兼容层（枚举回调/Module 静态/Memory 旧 API）；installLazyJavaBridge=懒加载+bridgeSource 字符串注入（Script.evaluate，agent 能力，非 gumjs 可照搬）。

【分析（对照 v7.0.13 全库 grep）】
• api.jvmti 消费点仅 2 处：class-model.js model_new（Java.use 类建模走 JVMTI 枚举类成员，jvmti==null 时反射 fallback）+ class-factory.js Java.choose 堆迭代。
• implementation 替换链（ArtMethodMangler：clone ArtMethod+flags+Nterp 位+ArtQuickCodeInterceptor+Deoptimize）【完全不消费 jvmti】→ 与"implementation 不触发"【无直接因果，已确认】。
• 该 patch 动机【推断·中置信】= ART35/HyperOS 上 libopenjdkjvmti.so 的 JVMTI env/枚举不稳定 → 短路让 Java.use/Java.choose 一律走最保守反射路径，属稳定性防御。→ 逐项：a) 不修 ART35 某路径（间接可能有利，中置信）；b) 不是自研方法替换/Dobby/native 入口（确认否）；c) 兼容性小修（确认是一半）。
• 但我们环境若 Java.use 在 ART35 也偶发异常（类建模 jvmti 枚举），可能同源【推断·中置信】——值得低成本对照实验。

【移植建议（可移植，纯字符串替换）】
⚠️ 坑：jvmtiProbe 是 minified 字段名（f/De/p），直接贴到我们未 minify 的 7.0.13 上 includes() 必失败。用我们原文：
```js
function patchJavaBridgeForArt35 (source) {
  return source.replace(/cachedJvmti\s*=\s*\[tryGetEnvJvmti\(vm,\s*this\.artRuntime\)\]/g,
                        'cachedJvmti = [null]');
}
```
落地：注入 bridge 源码前 JS 层应用（推荐①JavaBridgeBundle 加载器；②C++ 注入前字节替换=会随 bridge 版本漂移，不推荐；③改 bundle 内嵌=与上游冲突，不推荐）。

【对照实验（决定是否值得移）】移完后先试 `Java.use("android.app.Instrumentation").callApplicationOnCreate.implementation = function(){...}` 是否触发——5 分钟决定「JVMTI 短路是否是缺的拼图」，建议排在 PoC 锚点链路验证之后。

【t3 状态说明】t1/t2 均 completed、任务列表无 t3 对象（无法 claim/update），本产出以消息提交；请 captain 决定是否需要正式建 t 任务归档，或直接转交用户先跑 PoC。

【t3 调整稿（锚点机制研究·原创实现导向）】完整分析 ~/tmp-anchor/t3-mechanism-analysis.md，要点：

【机制说明（白盒·源码级）】patchJavaBridge 效果=把桥的 `api.jvmti` 恒置 null（禁用 JVMTI env 探测）。关键改动点行为链【已确认·v7.0.13 源码全链路】：Java.use → ClassModel.build → model_new 三分支枚举类成员 id：
① jvmti!=null → JVMTI get_class_methods/get_class_fields（id 来自 JVMTI）；
② art_api.available → 镜像直读 ArtMethod 数组（id=raw ArtMethod*，未编码）；
③ else → JNI 反射 fromReflectedMethod。
这些 id 成为 Method.handle → implementation 的 ArtMethodMangler(opaqueMethodId) → unwrapMethodId（奇偶解码/DecodeMethodId）。► patch 的机制意图=把③路径跳到②/③（jvmti 分支掐断），统一「类成员 id 来源」与「mangler 解码假设」的同源性。patch 不涉及 NativeCallback 封装/perform 语义/自研方法替换（无 Dobby/native 入口逻辑）——【已确认】。

【相关性（措辞按约定降级）】「推测，待真机验证」：ART35 上 JVMTI get_class_methods 返回的 jmethodID 与桥 DecodeMethodId/unwrap 假设编码不一致（数据源错配）→ 分支①下 method.handle 喂给 mangler 解码错/成空 → implementation 装上不触发；禁 JVMTI 走②（raw 同源）可能正是缓解机制。注意：不保证修复（若根因在 mangler 链其他环节/ART35 instrumentation，仍无效）；需对照实验判定。

【可移植性评估】机制可复刻（合规基线=frida-java-bridge 为 MIT 开源，我们持有官方 v7.0.13 全源码，改自持源码合法；算法助手 patch 是针对其 minified 私有构建的效果 hack，不作代码来源）；不建议照抄其字符串（token 不同且无意义）；成本低；预期收益【推测，待真机验证】。

【自实现方案（原创代码，等效机制）】
方案 A（推荐，源码级）：我们 bundle 里 class-model.js model_new 首行改 `jvmtiEnv * jvmti = java_api.jvmti;` → `jvmtiEnv * jvmti = NULL;`（一行 diff，强制走 art_api/反射路径）。
方案 B（不改源码）：注入前 token 替换（token 取我们自持源码）：
```js
function stripJvmtiFromJavaBridge (source) {
  const tokens = [
    'jvmtiEnv * jvmti = java_api.jvmti;',
    'cachedJvmti = [tryGetEnvJvmti(vm, this.artRuntime)];'
  ];
  for (const token of tokens) {
    if (source.includes(token)) return source.replace(token,
      token.startsWith('jvmtiEnv') ? 'jvmtiEnv * jvmti = NULL;' : 'cachedJvmti = [null];');
  }
  return source;
}
```
落地：JavaBridgeBundle 组装处注入前调用；或方案 A 直接改 bundle 源。

【验证（判定是否命中根因，5 分钟对照实验）】应用后跑 `Java.use("android.app.Instrumentation").callApplicationOnCreate.implementation = function(app){ console.log("IMPL-HIT"); return this.callApplicationOnCreate(app); }`：触发→【推测，待真机验证】jvmti 数据源错配是根因之一，机制有效；不触发→根因在 mangler 链其他环节，转 PoC 锚点路线。

